/**
 * Short names for the generated database types (docs/data-model.md §5).
 * database.types.ts is regenerated by `npm run db:types` and never edited by
 * hand; this file only gives its types readable names. Import them from here.
 */
import type { Database, Enums, Tables } from './database.types';

export type { Enums, Tables, TablesInsert, TablesUpdate } from './database.types';

// One row of each table.
export type Profile = Tables<'profiles'>;
export type TaskType = Tables<'task_types'>;
export type Task = Tables<'tasks'>;
export type Block = Tables<'blocks'>;
export type RecurringEvent = Tables<'recurring_events'>;
export type Habit = Tables<'habits'>;
export type HabitCheck = Tables<'habit_checks'>;
export type WeeklyReflection = Tables<'weekly_reflections'>;
export type MonthlyReflection = Tables<'monthly_reflections'>;
export type AiRequest = Tables<'ai_requests'>;
// Not "PushSubscription": the browser already has a type with that name.
export type PushSubscriptionRow = Tables<'push_subscriptions'>;
export type CalendarFeed = Tables<'calendar_feeds'>;
export type CalendarSubscription = Tables<'calendar_subscriptions'>;
export type ExternalEvent = Tables<'external_events'>;

// Enums.
export type ReflectionLevel = Enums<'reflection_level'>;
export type TaskFixation = Enums<'task_fixation'>;
export type TaskStatus = Enums<'task_status'>;
export type BlockStatus = Enums<'block_status'>;
export type BlockSource = Enums<'block_source'>;

// One row returned by type_stats().
export type TypeStat = Database['public']['Functions']['type_stats']['Returns'][number];
